#!/usr/bin/env python3
"""Small, self-contained, lossless compressor (Python standard library only).

Usage: python3 compress.py INPUT OUTPUT
       python3 compress.py --decompress INPUT OUTPUT
"""
import bz2
import sys
from pathlib import Path

MAGIC = b'CELL1\0'


def compress(data):
    return MAGIC + bz2.compress(data, compresslevel=9)


def decompress(data):
    if not data.startswith(MAGIC):
        raise ValueError('not a CELL1 compressed file')
    return bz2.decompress(data[len(MAGIC):])


def main():
    args = sys.argv[1:]
    decoding = bool(args and args[0] == '--decompress')
    if decoding:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit(__doc__)
    source, target = map(Path, args)
    result = (decompress if decoding else compress)(source.read_bytes())
    target.write_bytes(result)


if __name__ == '__main__':
    main()

"""Verify the CLI and repeated round trips, then report actual byte savings."""
from pathlib import Path
import subprocess
import sys
import time


def score():
    original = Path('corpus.txt').read_bytes()
    if not original:
        return 0.0
    for args in (['corpus.txt', 'out.bin'],
                 ['--decompress', 'out.bin', 'restored.txt']):
        subprocess.run([sys.executable, 'compress.py', *args], check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                       timeout=10)
    packed = Path('out.bin').read_bytes()
    if Path('restored.txt').read_bytes() != original:
        return 0.0
    import compress
    start = time.perf_counter()
    while True:
        trial = compress.compress(original)
        if trial != packed or compress.decompress(trial) != original:
            return 0.0
        if time.perf_counter() - start >= 0.4:
            break
    return 100.0 * (1.0 - len(packed) / len(original))


if __name__ == '__main__':
    try:
        result = score()
    except Exception:
        result = 0.0
    print(result)

